import React, { useState, useEffect, useRef } from "react"
import { doc, onSnapshot } from "firebase/firestore"
import { db } from "../../firebase/config"
import PortalLayout from "../../components/portal/PortalLayout"
import AppointmentCard, {
  PortalAppointment,
  PortalVehicle,
} from "../../components/portal/AppointmentCard"
import { graphql } from "gatsby"

interface BusinessInfo {
  name: string
  phone: string
  email: string
}

interface LookupResult {
  clientName: string
  vehicles: PortalVehicle[]
  upcoming: PortalAppointment[]
  past: PortalAppointment[]
}

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "not-found" }
  | { status: "error" }
  | { status: "success"; data: LookupResult }

export default function PortalIndexPage() {
  const [business, setBusiness] = useState<BusinessInfo>({
    name: "Garage Carlos Inc.",
    phone: "",
    email: "",
  })
  const [query, setQuery] = useState("")
  const [state, setState] = useState<State>({ status: "idle" })
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (!db) return
    const unsub = onSnapshot(doc(db, "settings", "business"), snap => {
      const d = snap.data()
      if (d) setBusiness({ name: d.name ?? "Auto Service", phone: d.phone ?? "", email: d.email ?? "" })
    })
    return unsub
  }, [])

  async function handleSearch(e: React.FormEvent) {
    e.preventDefault()
    const q = query.trim()
    if (!q) return

    setState({ status: "loading" })
    try {
      const apiBase = (process.env.GATSBY_API_URL ?? "").replace(/\/$/, "")
      const res = await fetch(`${apiBase}/api/lookup-client`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: q }),
      })
      const data = await res.json()

      if (!res.ok || data.error) {
        setState({ status: "error" })
        return
      }

      if (!data.found) {
        setState({ status: "not-found" })
        return
      }

      setState({
        status: "success",
        data: {
          clientName: data.clientName,
          vehicles: data.vehicles ?? [],
          upcoming: data.upcoming ?? [],
          past: data.past ?? [],
        },
      })
    } catch {
      setState({ status: "error" })
    }
  }

  function handleReset() {
    setState({ status: "idle" })
    setQuery("")
    setTimeout(() => inputRef.current?.focus(), 50)
  }

  return (
    <PortalLayout shopName={business.name} shopPhone={business.phone} shopEmail={business.email}>
      {/* Search form — always visible unless showing results */}
      {state.status !== "success" && (
        <div className="mb-8">
          <h1 className="text-xl font-bold text-gray-800 mb-1">Find My Appointments</h1>
          <p className="text-sm text-gray-500 mb-5">
            Enter the phone number or email address you used when booking.
          </p>

          <form onSubmit={handleSearch} className="flex gap-2">
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={e => {
                setQuery(e.target.value)
                if (state.status === "not-found" || state.status === "error") {
                  setState({ status: "idle" })
                }
              }}
              placeholder="514-555-0100 or you@example.com"
              className="flex-1 border border-gray-300 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              autoFocus
            />
            <button
              type="submit"
              disabled={!query.trim() || state.status === "loading"}
              className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold rounded-xl transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {state.status === "loading" ? (
                <>
                  <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Searching…
                </>
              ) : "Search"}
            </button>
          </form>

          {/* Feedback messages */}
          {state.status === "not-found" && (
            <div className="mt-4 bg-yellow-50 border border-yellow-200 rounded-xl p-4 text-sm text-yellow-800">
              <p className="font-medium mb-1">No account found</p>
              <p>
                We couldn't find any appointments for that phone number or email.
                Double-check your info or contact us directly.
              </p>
              {business.phone && (
                <p className="mt-2">
                  📞 <a href={`tel:${business.phone}`} className="underline">{business.phone}</a>
                </p>
              )}
            </div>
          )}

          {state.status === "error" && (
            <div className="mt-4 bg-red-50 border border-red-200 rounded-xl p-4 text-sm text-red-700">
              Something went wrong. Please try again or contact us.
            </div>
          )}
        </div>
      )}

      {/* Results */}
      {state.status === "success" && (
        <>
          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div>
              <h1 className="text-xl font-bold text-gray-800">
                Hi, {state.data.clientName.split(" ")[0]}!
              </h1>
              <p className="text-sm text-gray-500 mt-0.5">Your upcoming appointments.</p>
            </div>
            <button
              onClick={handleReset}
              className="text-xs text-blue-600 hover:text-blue-700 font-medium transition-colors"
            >
              ← Search again
            </button>
          </div>

          {/* Upcoming */}
          <section className="mb-8">
            {state.data.upcoming.length === 0 ? (
              <div className="bg-white rounded-xl border border-gray-200 p-6 text-center space-y-2">
                <p className="text-gray-400 text-sm">No upcoming appointments.</p>
                <p className="text-gray-400 text-sm">Contact us to schedule one.</p>
                {business.phone && (
                  <p className="text-sm">
                    <a href={`tel:${business.phone}`} className="text-blue-600 hover:underline">
                      {business.phone}
                    </a>
                  </p>
                )}
              </div>
            ) : (
              <div className="space-y-3">
                {state.data.upcoming.map(appt => (
                  <AppointmentCard
                    key={appt.id}
                    appointment={appt}
                    vehicles={state.data.vehicles}
                  />
                ))}
              </div>
            )}
          </section>

          {/* Past */}
          {state.data.past.length > 0 && (
            <section>
              <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wide mb-3">
                Past Appointments
              </h2>
              <div className="space-y-3">
                {state.data.past.map(appt => (
                  <AppointmentCard
                    key={appt.id}
                    appointment={appt}
                    vehicles={state.data.vehicles}
                  />
                ))}
              </div>
            </section>
          )}
        </>
      )}
    </PortalLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;